# Parse the graph from context
edges_text = context.split("The graph has the following edges:\n")[1].split("\n\nOperation:")[0]

graph = {}
for line in edges_text.strip().split('\n'):
    if ' -> ' in line:
        src, dst = line.split(' -> ')
        if src not in graph:
            graph[src] = []
        graph[src].append(dst)

# Build adjacency list
print("Graph adjacency list:")
for k, v in graph.items():
    print(f"{k} -> {v}")

start_node = "eccbc87e4b"

# BFS to find nodes at exactly depth 2
from collections import deque

# Track depth of each node
depth = {start_node: 0}
queue = deque([start_node])

while queue:
    current = queue.popleft()
    current_depth = depth[current]

    if current_depth >= 2:  # Don't need to go deeper than depth 2
        continue

    if current in graph:
        for neighbor in graph[current]:
            if neighbor not in depth:
                depth[neighbor] = current_depth + 1
                queue.append(neighbor)

print(f"\nDepths from {start_node}:")
for node, d in sorted(depth.items(), key=lambda x: x[1]):
    print(f"Depth {d}: {node}")

# Get nodes at exactly depth 2
depth_2_nodes = [node for node, d in depth.items() if d == 2]
print(f"\nNodes at exactly depth 2: {depth_2_nodes}")
